package com.bank.acid.model;

import java.math.BigDecimal;

public class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    public Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId; this.holderName = holderName; this.balance = balance;
    }
    public String getAccountId() { return accountId; }
    public BigDecimal getBalance() { return balance; }
    public void debit(BigDecimal amt) {
        if (balance.compareTo(amt) < 0) throw new IllegalStateException("Insufficient funds"); // Consistency
        balance = balance.subtract(amt);
    }
    public void credit(BigDecimal amt) { balance = balance.add(amt); }
}
