package com.bank.acid.service;

import com.bank.acid.model.Account;
import com.bank.acid.repository.AccountRepository;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());
    private final AccountRepository repo;
    public TransferService(AccountRepository repo) { this.repo = repo; }

    public void transfer(String fromId, String toId, BigDecimal amount) {
        Account from = repo.findById(fromId), to = repo.findById(toId);
        // Lock in a fixed order to avoid deadlock (Isolation via row locks / FOR UPDATE).
        Account first = fromId.compareTo(toId) < 0 ? from : to;
        Account second = first == from ? to : from;
        synchronized (first) {
            synchronized (second) {
                BigDecimal fromBefore = from.getBalance(), toBefore = to.getBalance();
                try {
                    from.debit(amount);   // leg 1
                    to.credit(amount);    // leg 2
                    // COMMIT point — both legs succeeded (Atomicity + Durability on real DB)
                    log.info(() -> "Transfer " + amount + " " + fromId + "->" + toId +
                            " ok. " + fromId + "=" + from.getBalance() + " " + toId + "=" + to.getBalance());
                } catch (RuntimeException ex) {
                    // ROLLBACK — restore both legs (Atomicity: all-or-nothing)
                    rollback(from, fromBefore, to, toBefore);
                    log.severe("Transfer failed, rolled back: " + ex.getMessage());
                    throw ex;
                }
            }
        }
    }

    private void rollback(Account from, BigDecimal fromBal, Account to, BigDecimal toBal) {
        // Simulate undo-log restore of both rows.
        BigDecimal fRestore = fromBal.subtract(from.getBalance());
        if (fRestore.signum() != 0) from.credit(fRestore);
        BigDecimal tRestore = toBal.subtract(to.getBalance());
        if (tRestore.signum() != 0) to.credit(tRestore);
    }
}
