package com.bank.acid;

import com.bank.acid.repository.AccountRepository;
import com.bank.acid.service.TransferService;
import java.math.BigDecimal;
import java.util.concurrent.*;

public class AcidApplication {
    public static void main(String[] args) throws InterruptedException {
        AccountRepository repo = new AccountRepository();
        TransferService svc = new TransferService(repo);

        svc.transfer("SAV2001", "CUR3001", new BigDecimal("50000")); // success

        // Two concurrent transfers serialize via locks (Isolation): no lost update.
        ExecutorService pool = Executors.newFixedThreadPool(2);
        for (int i = 0; i < 2; i++)
            pool.submit(() -> svc.transfer("SAV2001", "CUR3001", new BigDecimal("100000")));
        pool.shutdown(); pool.awaitTermination(3, TimeUnit.SECONDS);

        System.out.println("SAV2001 final: " + repo.findById("SAV2001").getBalance());
        System.out.println("CUR3001 final: " + repo.findById("CUR3001").getBalance());
    }
}
